import os
import json
from typing import Any, Dict, List, Optional

from openai import OpenAI


EXPENSE_SCHEMA: Dict[str, Any] = {
    "name": "normalized_expense",
    "schema": {
        "type": "object",
        "additionalProperties": False,
        "properties": {
            "merchant_name": {"type": ["string", "null"]},
            "transaction_date": {
                "type": ["string", "null"],
                "description": "ISO-8601 date string (YYYY-MM-DD) when available.",
            },
            "total_amount": {"type": ["number", "null"]},
            "currency": {"type": ["string", "null"], "description": "ISO 4217 currency code when available."},
            "tax_amount": {"type": ["number", "null"]},
            "tip_amount": {"type": ["number", "null"]},
            "subtotal_amount": {"type": ["number", "null"]},
            "payment_method": {"type": ["string", "null"]},
            "last4": {"type": ["string", "null"]},
            "invoice_number": {"type": ["string", "null"]},
            "receipt_number": {"type": ["string", "null"]},
            "category": {"type": ["string", "null"]},
            "line_items": {
                "type": "array",
                "items": {
                    "type": "object",
                    "additionalProperties": False,
                    "properties": {
                        "description": {"type": ["string", "null"]},
                        "quantity": {"type": ["number", "null"]},
                        "unit_price": {"type": ["number", "null"]},
                        "amount": {"type": ["number", "null"]},
                    },
                    "required": ["description", "quantity", "unit_price", "amount"],
                },
            },
            "raw_text": {"type": ["string", "null"]},
        },
        "required": [
            "merchant_name",
            "transaction_date",
            "total_amount",
            "currency",
            "tax_amount",
            "tip_amount",
            "subtotal_amount",
            "payment_method",
            "last4",
            "invoice_number",
            "receipt_number",
            "category",
            "line_items",
            "raw_text",
        ],
    },
}


def _coerce_json_text(text: str) -> Dict[str, Any]:
    try:
        return json.loads(text)
    except Exception:
        start = text.find("{")
        end = text.rfind("}")
        if start != -1 and end != -1 and end > start:
            return json.loads(text[start : end + 1])
        raise


def normalize_expense_fields(
    extracted_fields: Dict[str, Any],
    raw_document_text: Optional[str] = None,
    model: str = "gpt-4o-mini",
) -> Dict[str, Any]:
    client = OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))

    payload = {
        "extracted_fields": extracted_fields,
        "raw_document_text": raw_document_text,
        "instructions": (
            "Normalize the extracted expense data into the target schema. "
            "Preserve available values, infer standard formats when safe, "
            "and set unknown fields to null. Ensure amounts are numeric."
        ),
    }

    response = client.responses.create(
        model=model,
        input=[
            {
                "role": "system",
                "content": "You transform expense document extraction results into a standardized JSON object.",
            },
            {
                "role": "user",
                "content": json.dumps(payload, ensure_ascii=False),
            },
        ],
        response_format={
            "type": "json_schema",
            "json_schema": EXPENSE_SCHEMA,
        },
    )

    text = getattr(response, "output_text", None)
    if not text:
        try:
            text = response.output[0].content[0].text
        except Exception:
            text = json.dumps(response.model_dump())
    result = _coerce_json_text(text)

    for key in EXPENSE_SCHEMA["schema"]["properties"].keys():
        result.setdefault(key, None)
    if not isinstance(result.get("line_items"), list):
        result["line_items"] = []

    return result
